package dev.vitrail.glsl;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Splices code generated by Chunks Fade In into the translated terrain stages. No animation
 * timing or fade curves live here: the optional mod owns both those and the generated code.
 */
public final class ChunkFadeShader {
	private static final Pattern FIRST_COLOUR = Pattern.compile(
			"layout\\s*\\(\\s*location\\s*=\\s*0\\s*\\)\\s*out\\s+vec4\\s+(\\w+)\\s*;");

	private ChunkFadeShader() {
	}

	/** Displaces the decoded section local position before it is placed inside its region. */
	public static String vertex(String source, String declarations, String init) {
		TokenStream tokens = new TokenStream(GlslLexer.lex(source));
		int function = function(tokens, SodiumVertex.PROLOGUE);
		int local = -1;
		for (int i = function; i < tokens.size(); i++) {
			if (tokens.get(i).identifier("ofLocal")) {
				local = i;
				break;
			}
		}
		if (local < 0) {
			throw new IllegalArgumentException("Missing terrain local position");
		}
		int end = local;
		while (end < tokens.size() && !tokens.get(end).operator(";")) {
			end++;
		}
		if (end == tokens.size()) {
			throw new IllegalArgumentException("Unterminated terrain local position");
		}
		tokens.inject(end, ";\n" + init + "\n");
		int start = tokens.significantBefore(function);
		tokens.inject(start, declarations + "\nvoid");
		return tokens.join();
	}

	/** Wraps the whole entry point so an early return cannot bypass the fade. */
	public static String fragment(String source, String declarations, String tail) {
		int versionEnd = source.indexOf('\n');
		if (!source.startsWith("#version") || versionEnd < 0) {
			throw new IllegalArgumentException("Missing translated shader version");
		}
		// Packs retain conditional entry points. A macro renames every active definition and its
		// prototype together, instead of guessing which #if branch the compiler will select.
		int headerEnd = versionEnd + 1;
		int offset = 0;
		for (GlslLexer.Token token : GlslLexer.lex(source)) {
			if ("extension".equals(token.directive())) {
				int newline = source.indexOf('\n', offset + token.text().length());
				headerEnd = newline < 0 ? source.length() : newline + 1;
			}
			offset += token.text().length();
		}
		return source.substring(0, headerEnd) + declarations
				+ "\n#define main ofCfiMain\n" + source.substring(headerEnd)
				+ "\n#undef main\nvoid main() {\nofCfiMain();\n" + tail + "\n}\n";
	}

	/** The first translated colour output, or empty for an output this bridge cannot fade. */
	public static String firstColour(String source) {
		Matcher match = FIRST_COLOUR.matcher(source);
		return match.find() ? match.group(1) : "";
	}

	private static int function(TokenStream tokens, String name) {
		for (int i = 0; i < tokens.size(); i++) {
			if (tokens.get(i).directive() == null && tokens.get(i).identifier(name)) {
				int before = tokens.significantBefore(i);
				if (before >= 0 && tokens.get(before).identifier("void")) {
					return i;
				}
			}
		}
		throw new IllegalArgumentException("Missing terrain function " + name);
	}
}
